/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l04/gameplay/entities/0029eb20.c, FUN_L04_0029eb20. */
s32 Path_AdvanceMoby(struct Moby *m, PathPoints_eb20_9FCF0 *path, s32 i, s32 dir, f32 dist) {
    Vec4 seg;
    Vec4 rel;
    s32 next;
    f32 len;
    f32 along;

    next = path_next_eb20_9FCF0(path, i, dir);
    FastVecSub_r(&seg, &path->point[next], &path->point[i]);
    len = FastVecLength_r(&seg);
    vec_scale_to_length_r(&seg, &seg, 1.0f);
    FastVecSub_r(&rel, &m->pos, &path->point[i]);
    along = FastVecDot_r(&rel, &seg) + dist;
    if (len < along) {
        i = next;
        next = path_next_eb20_9FCF0(path, i, dir);
        FastVecSub_r(&seg, &path->point[next], &path->point[i]);
        along = along - len;
        vec_scale_to_length_r(&seg, &seg, 1.0f);
    }
    vec_scale_to_length_r(&seg, &seg, along);
    FastVecAdd_r(&m->pos, &seg, &path->point[i]);
    return i;
}
