/* Class 0x55 swarm controller: counts its children and steers them around the origin. */
void update_class_55_swarm_controller(struct PMoby *moby) {
    SwarmVars *data = (SwarmVars *)moby->pvars;
    struct PMoby **children;
    struct PMoby *other;
    f32 distance;
    f32 angle;
    f32 angle2;
    f32 speed;
    f32 size;
    f32 effect[8];

    if (*(int *)&eudora_swarm_initialized == 0) {
        f32 *effect_dest = eudora_swarm_steer_params;
        libc_memset(effect, 0, 0x20);
        effect[1] = IntToFloat(data->child_count) * 2.073f;
        effect[3] = 2.0f;
        effect[4] = 1.0f;
        effect[5] = 1.0f;
        *(int *)&eudora_swarm_initialized = 1;
        __builtin_memcpy(effect_dest, effect, 0x20);
    }
    if (data->initialized == 0) {
        qcopy(&data->origin, &moby->pos);
        data->angle = 0.0f;
    } else if (data->child_count == 0) {
        for (other = (struct PMoby *)eudora_moby_list; other != 0; other = other->next) {
            if ((s8)other->state >= 0 && other->oclass == 0x55) {
                data->child_count++;
            }
        }
        eudora_swarm_steer_params[1] = IntToFloat(data->child_count) * 2.073f;
    }
    if (data->path_index == -1) {
        data->angle = FastAddRots(data->angle, frame_scale * 0.0034906587f);
        moby->pos.x = data->origin.x + data->radius * FastCos(data->angle);
        moby->pos.y = data->origin.y + data->radius * FastSin(data->angle);
    } else if (data->initialized != 0) {
        s32 i;
        distance = 10000.0f;
        for (i = 0; i < data->count; i++) {
            f32 d = vec_distance_xy((float *)&moby->pos, (float *)&data->children[i]->pos);
            if (d < distance) distance = d;
        }
        speed = 0.0f;
        if (distance < 3.0f) speed = 3.0f - distance;
        data->direction = Path_AdvanceMoby((struct Moby *)moby, (PathPoints_eb20_9FCF0 *)eudora_paths[data->path_index], data->direction, 1, speed);
    }
    if (data->initialized == 0) {
        s32 i;
        struct PMoby *child;
        data->initialized = 1;
        data->child_count = 0;
        for (i = 0; i < data->count; i++) {
            data->children[i] = 0;
            child = (struct PMoby *)CreateMoby(0x55);
            if (child != 0) {
                SwarmPartVars *part = (SwarmPartVars *)child->pvars;
                data->children[i] = child;
                child->update_dist = 0x7f;
                child->draw_dist = 0x7f;
                child->scale *= random_float_between(0.7f, 1.3f);
                child->rot.z = random_angle_radians();
                child->anim_speed = random_float_between(0.6f, 1.2f);
                clear_u64_value((float *)&part->velocity);
                part->unk44 = 0;
                part->unk4C = 10.0f;
                qcopy(&child->pos, &moby->pos);
                angle = random_angle_radians();
                angle2 = random_angle_radians();
                size = random_float_between(0.6f, 0.9f);
                child->pos.x += FastCos(angle) * FastSin(angle2) * size;
                child->pos.y += FastSin(angle) * FastSin(angle2) * size;
                child->pos.z += FastCos(angle2) * size;
                part->unk50 = 0;
                part->leader_pos = &moby->pos;
                part->unk58 = 0;
                part->unk70 = 1.694f;
                part->unk74 = 1.694f;
                part->unk48 = 1.056f;
                part->unk5C = -1;
                part->unk40 = 0.003f;
                part->unk5E = 2;
                part->oclass = 0x55;
                part->unk90 = 1.0f;
                part->unk62 = 0x1ee;
                part->unk94 = 5.0f;
                moby_build_matrix(child);
            }
        }
    } else {
        s32 i;
        struct PMoby *child;
        for (i = 0; i < data->count; i++) {
            void *part;
            children = data->children;
            child = children[i];
            part = child->pvars;
            eudora_swarm_steer_params[6] = ((data->radius * 7.753f) / 1800.0f) * frame_scale * ((child->anim_speed + 1.0f) * 0.5f) * 0.05f * g_frame_scale_sq * ((child->anim_speed + 1.0f) * 0.5f);
            eudora_swarm_steer_params[7] = (((data->radius * 7.753f) / 1800.0f) * frame_scale) * ((child->anim_speed + 1.0f) * 0.5f);
            steer_child_moby(children, data->count, child, part, eudora_swarm_steer_params);
            update_moby_movement_with_sphere_collision(0.0f, child, part, eudora_swarm_steer_params);
        }
    }
}
