/* Flock steering for moby m: picks its path target, pushes away from same-class mobys within 3 units,
 * keeps its spacing to the target unless another flock member is closer to it, writes the steer point
 * to out and returns the yaw toward it. (The passed speed is recomputed from the moby's state.) */
float compute_circular_saw_flock_steering(void *m, void *out, float speed) {
    float sep[4];
    float tgt[4];
    float pad[4][4];
    char *d = ((char *)((Moby *)m)->pvars);
    char *o;
    float dist;
    float w;
    int alone;
    int fast = 0;
    if (*(int *)(d + 0x38) != 0 || *(short *)(d + 0x136) != 0) fast = 1;
    if (fast) {
        speed = *(float *)(d + 0x140) + *(float *)(d + 0x140);
    } else {
        speed = *(float *)(d + 0x140);
    }
    FindNearestTargetMoby_k(m, tgt, speed);
    dist = vec_distance_xy((float *)((char *)m + 0x10), tgt);
    clear_u64_value(out);
    alone = 1;
    o = eudora_moby_list;
    w = 0.0f;
    for (; o != 0; o = *(char **)(o + 0x28)) {
        if (o == m || *(short *)(o + 0xA6) != ((Moby *)m)->oclass) continue;
        if (vec_distance_xy((float *)(o + 0x10), (float *)((char *)m + 0x10)) < 3.0f) {
            FastVecSub(sep, (char *)m + 0x10, o + 0x10);
            FastVecScale(sep, sep, *(float *)&eudora_circular_saw_separation_weight);
            FastVecAdd(out, out, sep);
            w += *(float *)&eudora_circular_saw_separation_weight;
        }
        if (vec_distance_xy((float *)(o + 0x10), tgt) < dist) alone = 0;
    }
    if (!alone) {
        float k;
        FastVecSub(sep, (char *)m + 0x10, tgt);
        if (dist < 4.5f) {
            k = 5.0f;
        } else if (5.5f < dist) {
            k = -5.0f;
        } else {
            k = 0.0f;
        }
        vec_scale_to_length(sep, sep, k * 10.0f);
        w += 10.0f;
        FastVecAdd(out, out, sep);
        FastVecScale(out, out, 1.0f / w);
        FastVecAdd(out, out, (char *)m + 0x10);
    } else {
        qcopy(out, tgt);
    }
    if (vec_distance_xy((float *)((char *)m + 0x10), (float *)out) < 1.0f) {
        qcopy(out, (char *)m + 0x10);
        return fast_atan2(tgt[0] - ((Moby *)m)->pos.x, tgt[1] - ((Moby *)m)->pos.y);
    }
    return fast_atan2(((float *)out)[0] - ((Moby *)m)->pos.x, ((float *)out)[1] - ((Moby *)m)->pos.y);
}
