extern short eudora_smoke_puff_size;

/* Lays a trail of smoke puffs from FROM to TO with a burst at each end.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l04/gameplay/entities/0029eb20.c, FUN_L04_002c41e0. */
void spawn_smoke_puff_trail_with_endpoint_bursts(void *owner, void *from, void *to, int count, float a, float b) {
    Vec4 step;
    Vec4 at;
    Vec4 vel;
    float grow;
    int i;
    int tint;
    int grey;
    float size;
    Puff *puff;
    PuffTail *tail;
    int spin;

    FastVecSub(&step, to, from);
    FastVecScale(&step, &step, 1.0f / (float)count);
    grow = (b - a) / (float)count;
    vel.q = 0;
    vel.f[3] = 1.0f;
    vel.f[2] = 0.01f;
    for (i = 0; i < count; i++) {
        FastVecScale(&at, &step, IntToFloat(i));
        FastVecAdd(&at, from, &at);
        vel.f[0] = randf_sym(0.0f, 0.005f);
        vel.f[1] = randf_sym(0.0f, 0.005f);
        vel.f[2] = random_float_between((*(f32 *)&eudora_smoke_puff_rise_speed) * 0.1f, (*(f32 *)&eudora_smoke_puff_rise_speed));
        tint = rand_range(0x40, 0x70);
        grey = rand_range(0x40, 0x7F);
        grey = grey | (grey << 16 | grey << 8);
        size = random_float_between(1.0f, 1.02f);
        spin = rand_range(-2, 2);
        puff = PartType23Spawn(&at, (*(f32 *)&eudora_smoke_puff_size), 1.0f, size, spin, &vel, grow + a * 210000.0f, tint << 24 | grey);
        if (puff != 0) {
            tail = &puff->tail;
            if (random_integer_below(2) != 0) {
                puff->alpha = 0x7E;
                grey = rand_range(0x60, 0xE0);
                grey = grey | (grey << 16 | grey << 8);
                puff->color = tint << 24 | grey;
            }
            puff->life = scale_ticks(0x5A);
            tail->mode = 2;
            tail->tint = tint;
            tail->fade = scale_ticks(0x5A);
        }
    }
    vel.f[0] = FastCos(random_angle_radians()) * 0.05f;
    vel.f[1] = FastSin(random_angle_radians()) * 0.05f;
    vel.f[2] = 0.0f;
    vel.f[2] = random_float_between(0.01f, 0.03f);
    PartType21Spawn(from, &vel, 0x4F007FFF, 0x1FFFFFFF, rand_range(scale_ticks(10), scale_ticks(20)), 1,
                10000.0f);
    vel.f[0] = FastCos(random_angle_radians()) * 0.05f;
    vel.f[1] = FastSin(random_angle_radians()) * 0.05f;
    vel.f[2] = 0.0f;
    vel.f[2] = random_float_between(0.01f, 0.03f);
    PartType21Spawn(to, &vel, 0x4F007FFF, 0x1FFFFFFF, rand_range(scale_ticks(10), scale_ticks(20)), 1,
                20000.0f);
}
