/* Door update: follows its lever's travel, pushes the lever back while opening, and runs the motor sounds.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l04/gameplay/entities/0029eb20.c, FUN_L04_002c6bb8. */
void platform_booster_update(struct Moby *m) {
    DoorVars *v = (DoorVars *)m->pvars;
    f32 prev;
    struct Moby *lever;
    LeverVars *lv;
    u8 *slot;

    prev = m->anim_time;
    if (v == 0) {
        DeleteMoby(m);
        return;
    }
    switch (m->state) {
    case 0:
        MobyBlendAnimation_r2(m, 1, 0, scale_ticks(300));
        m->state = 1;
        m->anim_speed = 0;
        v->voice = -1;
        break;
    case 1:
        if (v->lever == -1) {
            break;
        }
        lever = &eudora_mobys_r2[v->lever];
        if (lever->oclass != 0x118) {
            break;
        }
        lv = (LeverVars *)lever->pvars;
        if (lever->state == 3) {
            m->anim_time = 1.0f - lv->travel;
        } else if (lv->travel != 1.0f ||
                   (v->target != -1 && v->locked == 0 &&
                    ((u32)g_hero.state.control_mode < 2 || g_hero.state.control_mode == 9 ||
                     g_hero.state.control_mode == 12) &&
                    g_hero.ground_moby == &eudora_mobys_r2[v->target])) {
            m->state = 2;
        }
        if (m->anim_time != prev) {
            if (lv->travel != 1.0f && lv->travel != 0.0f) {
                if (Sound_IsPlaying(m, v->voice) == 0) {
                    v->voice = Moby_PlaySound_r3(0, 4, (int)m);
                }
            } else {
                if (Sound_IsPlaying(m, v->voice) != 0) {
                    if (v->voice != -1) {
                        slot = voice_pool + v->voice * 0x70;
                        if (*(struct Moby **)(slot + 0x88) == m && slot[0x74] != 0) {
                            Sound_StopSlot(v->voice);
                        }
                    }
                    v->voice = -1;
                }
                Moby_PlaySound_r3(1, 0, (int)m);
            }
        } else if (Sound_IsPlaying(m, v->voice) != 0) {
            if (v->voice != -1) {
                slot = voice_pool + v->voice * 0x70;
                if (*(struct Moby **)(slot + 0x88) == m && slot[0x74] != 0) {
                    Sound_StopSlot(v->voice);
                }
            }
            v->voice = -1;
        }
        break;
    case 2: {
        struct Moby *link;
        LeverVars *link_vars;

        m->anim_time = prev + (*(float *)&g_frame_time_r2) * 0.5f;
        if (1.0f < m->anim_time) {
            m->anim_time = 1.0f;
        }
        if (v->lever == -1) {
            break;
        }
        link = &eudora_mobys_r2[v->lever];
        if (link->oclass != 0x118) {
            break;
        }
        link_vars = (LeverVars *)link->pvars;
        if (link->state == 3) {
            m->anim_time = 1.0f - link_vars->travel;
            m->state = 1;
        } else {
            link_vars->travel = 1.0f - m->anim_time;
            link_vars->spin = link_vars->travel * (link_vars->rate * 6.2831855f);
        }
        if (m->anim_time != prev) {
            if (link_vars->travel == 1.0f || link_vars->travel == 0.0f) {
                if (Sound_IsPlaying(m, v->voice) != 0) {
                    if (v->voice != -1) {
                        slot = voice_pool + v->voice * 0x70;
                        if (*(struct Moby **)(slot + 0x88) == m && slot[0x74] != 0) {
                            Sound_StopSlot(v->voice);
                        }
                    }
                    v->voice = -1;
                }
                Moby_PlaySound_r3(1, 0, (int)m);
            } else if (Sound_IsPlaying(m, v->voice) == 0) {
                v->voice = Moby_PlaySound_r3(0, 4, (int)m);
            }
        } else if (Sound_IsPlaying(m, v->voice) != 0) {
            if (v->voice != -1) {
                slot = voice_pool + v->voice * 0x70;
                if (*(struct Moby **)(slot + 0x88) == m && slot[0x74] != 0) {
                    Sound_StopSlot(v->voice);
                }
            }
            v->voice = -1;
        }
        break;
    }
    }
    if (v->target != -1) {
        Moby_GetJointWorldPos(m, 0, &eudora_mobys_r2[v->target].pos);
    }
}
